class FlightWatchesPage extends StatefulWidget{const FlightWatchesPage({super.key});@override State<FlightWatchesPage> createState()=>_FlightWatchesPageState();}
class _FlightWatchesPageState extends State<FlightWatchesPage>{List<Map<String,dynamic>>rows=[];@override void initState(){super.initState();load();}Future<void>load()async{rows=active(await Store.list('flightWatches'));if(rows.isEmpty){rows=[{'id':newId(),'origin':'FLL','destination':'HAV','targetPrice':180.0,'lastPrice':0.0,'deleted':false},{'id':newId(),'origin':'MIA','destination':'HAV','targetPrice':180.0,'lastPrice':0.0,'deleted':false}];await Store.saveList('flightWatches',rows);}if(mounted)setState((){});}Future<void>edit([Map<String,dynamic>?e])async{final o=TextEditingController(text:'${e?['origin']??'FLL'}'),d=TextEditingController(text:'${e?['destination']??'HAV'}'),t=TextEditingController(text:'${e?['targetPrice']??180}'),l=TextEditingController(text:'${e?['lastPrice']??0}');final ok=await showDialog<bool>(context:context,builder:(_)=>AlertDialog(title:const Text('Vigilar ruta'),content:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:o,decoration:const InputDecoration(labelText:'Origen')),const SizedBox(height:8),TextField(controller:d,decoration:const InputDecoration(labelText:'Destino')),const SizedBox(height:8),TextField(controller:t,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Avisarme si baja de')),const SizedBox(height:8),TextField(controller:l,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Último precio observado'))])),actions:[TextButton(onPressed:()=>Navigator.pop(context,false),child:const Text('Cancelar')),FilledButton(onPressed:()=>Navigator.pop(context,true),child:const Text('Guardar'))]));if(ok==true){final all=await Store.list('flightWatches');final item={'id':e?['id']??newId(),'origin':o.text.trim().toUpperCase(),'destination':d.text.trim().toUpperCase(),'targetPrice':number(t.text),'lastPrice':number(l.text),'deleted':false};final i=all.indexWhere((x)=>x['id']==item['id']);if(i>=0)all[i]={...all[i],...item};else all.add(item);await Store.saveList('flightWatches',all);load();}}
Future<void>searchFlight(Map<String,dynamic>e)async{final q=Uri.encodeComponent('${e['origin']} ${e['destination']} cheap flights');await launchUrl(Uri.parse('https://www.google.com/travel/flights?q=$q'),mode:LaunchMode.externalApplication);}
@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Vuelos y alertas')),body:ListView(padding:const EdgeInsets.all(12),children:[const Card(child:Padding(padding:EdgeInsets.all(12),child:Text('Guarda tus rutas y precios objetivo. Esta versión abre la búsqueda de vuelos y compara el precio que registres. La alerta automática en segundo plano se activará cuando conectemos un proveedor de vuelos/API.'))),for(final e in rows)Card(child:ListTile(leading:const Icon(Icons.flight_takeoff),title:Text('${e['origin']} → ${e['destination']}'),subtitle:Text('Objetivo: ${money(number(e['targetPrice']))} · Observado: ${number(e['lastPrice'])>0?money(number(e['lastPrice'])):'—'}'),trailing:Wrap(children:[IconButton(icon:const Icon(Icons.search),onPressed:()=>searchFlight(e)),IconButton(icon:const Icon(Icons.edit),onPressed:()=>edit(e))])))]),floatingActionButton:FloatingActionButton(onPressed:()=>edit(),child:const Icon(Icons.add)));
}
